package byocproxy

import (
	"fmt"

	"sigs.k8s.io/yaml"
)

const appConfigHeader = `# Generated by yba-ctl from byocApiProxy.appConfig in yba-ctl.yml.
# Do not edit; changes are overwritten on install, upgrade and reconfigure.
# Properties set here take precedence over the application's bundled defaults and
# their ${ENV} placeholders; byoc-api-proxy.env only affects properties not set here.
`

// RenderAppConfig produces the application.yaml overlay contents: the operator's
// byocApiProxy.appConfig deep-merged on top of installer-derived defaults.
func RenderAppConfig(defaults, appConfig map[string]interface{}) ([]byte, error) {
	merged := MergeMaps(defaults, appConfig)
	out, err := yaml.Marshal(merged)
	if err != nil {
		return nil, fmt.Errorf("failed to render byoc-api-proxy application.yaml: %w", err)
	}
	return append([]byte(appConfigHeader), out...), nil
}

// MergeMaps returns base with override deep-merged on top: map values merge
// recursively, any other value in override replaces the base value. Neither
// input map is modified.
func MergeMaps(base, override map[string]interface{}) map[string]interface{} {
	merged := make(map[string]interface{}, len(base)+len(override))
	for k, v := range base {
		merged[k] = v
	}
	for k, v := range override {
		overrideMap, overrideIsMap := asStringMap(v)
		baseMap, baseIsMap := asStringMap(merged[k])
		if overrideIsMap && baseIsMap {
			merged[k] = MergeMaps(baseMap, overrideMap)
		} else {
			merged[k] = v
		}
	}
	return merged
}

func asStringMap(v interface{}) (map[string]interface{}, bool) {
	switch m := v.(type) {
	case map[string]interface{}:
		return m, true
	case map[interface{}]interface{}:
		converted := make(map[string]interface{}, len(m))
		for key, value := range m {
			converted[fmt.Sprint(key)] = value
		}
		return converted, true
	default:
		return nil, false
	}
}

// Configuration requirements (which fields must be set) do not live here: they
// are owned by the release package (systemd/install.sh --validate) so new
// required fields never need yba-ctl changes.
